package com.suresh.lifeos;
import android.app.*;import android.content.*;import android.os.*;import java.time.*;import java.util.*;
public class AlarmReceiver extends BroadcastReceiver{
 public void onReceive(Context c,Intent i){long id=i.getLongExtra("task_id",-1);Intent open=new Intent(c,MainActivity.class);open.putExtra("task_id",id);open.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP);PendingIntent pi=PendingIntent.getActivity(c,(int)id,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(c,LifeApp.CH):new Notification.Builder(c);b.setSmallIcon(android.R.drawable.ic_lock_idle_alarm).setContentTitle("Suresh Life OS").setContentText("Private reminder due now — unlock to view.").setVisibility(Notification.VISIBILITY_SECRET).setCategory(Notification.CATEGORY_ALARM).setPriority(Notification.PRIORITY_MAX).setAutoCancel(true).setContentIntent(pi);c.getSystemService(NotificationManager.class).notify((int)id,b.build());}
 public static void scheduleToday(Context c){Store s=Store.get(c);int dow=LocalDate.now().getDayOfWeek().getValue();for(Map<String,String>x:s.q("SELECT * FROM tasks WHERE active=1")){String days=x.get("days");if(days==null||!Arrays.asList(days.split(",")).contains(String.valueOf(dow)))continue;try{int min=Integer.parseInt(x.get("start_min"));ZonedDateTime z=LocalDate.now().atTime(min/60,min%60).atZone(ZoneId.systemDefault());if(z.toInstant().toEpochMilli()<=System.currentTimeMillis())continue;long id=Long.parseLong(x.get("id"));Intent i=new Intent(c,AlarmReceiver.class).putExtra("task_id",id);PendingIntent p=PendingIntent.getBroadcast(c,(int)id,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);AlarmManager a=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);a.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,z.toInstant().toEpochMilli(),p);}catch(Exception ignored){}}}
}
